import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, PlaneGeometry, Color } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  const timelines = [];
  const disposables = [];

  // 1. BACKDROP: Full-bleed editorial plate 7 x 5.5 units at z=0 with vertical gradient
  const backdropGeo = new THREE.PlaneGeometry(7, 5.5);
  disposables.push(backdropGeo);

  const color1 = new THREE.Color('#0b0b10');
  const color2 = new THREE.Color('#14141a');

  // Vertical gradient: #14141a (bottom, uv.y=0) to #0b0b10 (top, uv.y=1)
  const gradientNode = mix(
    vec3(color2.r, color2.g, color2.b),
    vec3(color1.r, color1.g, color1.b),
    uv().y
  );

  const backdropMat = new THREE.MeshBasicNodeMaterial({
    colorNode: gradientNode
  });
  disposables.push(backdropMat);

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = 0;
  group.add(backdrop);

  // 2. TEXT ELEMENTS (all left-aligned at x=-3.1 on strict 0.25-unit baseline grid)

  // Kicker: "NOVA ATELIER / JOURNAL" (18px 700, tracking 0.12em) at y=1.7
  const kickerText = ctx.fontAtlas.createText('NOVA ATELIER / JOURNAL', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 18 * 0.12
  });
  kickerText.position.set(-3.1, 1.7, 0.01);
  group.add(kickerText);

  // Hero line 1: "PRECISION IS" (124px 600, tracking -0.015em) at y=0.9
  const heroLine1 = ctx.fontAtlas.createText('PRECISION IS', {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 124 * -0.015
  });
  heroLine1.position.set(-3.1, 0.9, 0.01);
  group.add(heroLine1);

  // Hero line 1 - print-depth shadow (#16161d letterpress edge) 0.02 units behind
  const heroLine1Depth = ctx.fontAtlas.createText('PRECISION IS', {
    fontSize: 124,
    color: '#16161d',
    align: 'left',
    letterSpacingPx: 124 * -0.015
  });
  heroLine1Depth.position.set(-3.1, 0.9, -0.01);
  group.add(heroLine1Depth);

  // Hero line 2: "A HABIT." (124px 600, tracking -0.015em) at y=0.25
  const heroLine2 = ctx.fontAtlas.createText('A HABIT.', {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 124 * -0.015
  });
  heroLine2.position.set(-3.1, 0.25, 0.01);
  group.add(heroLine2);

  // Hero line 2 - print-depth shadow 0.02 units behind
  const heroLine2Depth = ctx.fontAtlas.createText('A HABIT.', {
    fontSize: 124,
    color: '#16161d',
    align: 'left',
    letterSpacingPx: 124 * -0.015
  });
  heroLine2Depth.position.set(-3.1, 0.25, -0.01);
  group.add(heroLine2Depth);

  // Accent underline rule: 2.2 x 0.05 units, #ff2a38 at emissive 1.2, y=-0.15
  const ruleGeo = new THREE.PlaneGeometry(2.2, 0.05);
  disposables.push(ruleGeo);

  const ruleMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#ff2a38'),
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 1.2,
    metalness: 0,
    roughness: 1
  });
  disposables.push(ruleMat);

  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(-3.1, -0.15, 0.02);
  rule.scale.x = 0; // Starts at scaleX=0 for drawing animation
  group.add(rule);

  // Body paragraph (26px 400, max-width 4.5 units) at y=-0.8
  const bodyText = ctx.fontAtlas.createText(
    'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
    {
      fontSize: 26,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 450
    }
  );
  bodyText.position.set(-3.1, -0.8, 0.01);
  group.add(bodyText);

  // Caption: "ISSUE 12 / JULY 2026" (18px 400) at y=-1.9
  const captionText = ctx.fontAtlas.createText('ISSUE 12 / JULY 2026', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'left'
  });
  captionText.position.set(-3.1, -1.9, 0.01);
  group.add(captionText);

  // 3. ENTRANCE ANIMATIONS
  // Rise-in per block top-to-bottom: y offset +0.4→0, opacity 0→1, 700ms, power3.out
  // with 80ms stagger between blocks

  const textBlocks = [
    { objs: [kickerText], startY: 1.7, delay: 0 },
    { objs: [heroLine1, heroLine1Depth], startY: 0.9, delay: 0.08 },
    { objs: [heroLine2, heroLine2Depth], startY: 0.25, delay: 0.16 },
    { objs: [bodyText], startY: -0.8, delay: 0.24 },
    { objs: [captionText], startY: -1.9, delay: 0.32 }
  ];

  textBlocks.forEach(({ objs, startY, delay }) => {
    objs.forEach(obj => {
      // Set starting position: offset upward by 0.4
      obj.position.y = startY + 0.4;

      // Set initial opacity to 0
      obj.traverse((child) => {
        if (child.material) {
          child.material.opacity = 0;
          child.material.transparent = true;
        }
      });

      const tl = gsap.timeline();

      // Animate position: offset +0.4 → 0 (rise-in)
      tl.to(obj.position, {
        y: startY,
        duration: 0.7,
        ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)' // power3.out equivalent
      }, delay);

      // Animate opacity: 0 → 1 (parallel with position)
      const opacityProxy = { val: 0 };
      tl.to(opacityProxy, {
        val: 1,
        duration: 0.7,
        ease: 'power2.out',
        onUpdate() {
          obj.traverse((child) => {
            if (child.material) {
              child.material.opacity = opacityProxy.val;
            }
          });
        }
      }, delay);

      timelines.push(tl);
    });
  });

  // Rule animation: scaleX 0 → 1, starts after hero lands
  // Hero line 1 delay 0.08s + rise-in duration 0.7s = rule starts at 0.78s
  const ruleDelay = 0.08 + 0.7;
  const ruleTl = gsap.timeline();
  ruleTl.to(rule.scale, {
    x: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
  }, ruleDelay);
  timelines.push(ruleTl);

  // 4. CLEANUP
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(obj => obj.dispose());
  };

  return group;
}
